To approach our target---a fast local iteration for nonsmooth optimization---let us recall, as motivation, the classical foundations of gradient descent (GD). For some function $h$, denote the linear approximation of $h$ centered at some differentiable iterate $\tx$ by \[\ell_{\tx}^{h}(x)\equiv h(\tx) + \nabla h(\tx)^T(x-\tx),\]


\begin{defn} \textbf{(Survey Descent Iteration $\boldsymbol{\left\{\left(P_i^\S\right)\right\}_{i=1}^k}$)\label{def:SD_Method}} Given a \textit{survey} of $k$ points, $\S=\left\{ s_{i}\right\} _{i=1}^{k}$, at which the nonsmooth objective $h$ is differentiable and a step-control parameter $L$, for each $i=1,{\dots},k$, define the \textit{$i$-th subproblem} $\left(P_i^\S\right)$ as follows:
\begin{align}
\min_{x}\ & \left\| x-\left(s_{i}-\frac{1}{L}\nabla h\left(s_{i}\right)\right)\right\| _{2}^{2}\label{eq:SD_objective}\\
\mathrm{s.t.}\ & \ell_{s_j}^{h}(x)+\frac{L}{2}\left\| x-s_{j}\right\| _{2}^{2}\leq \ell_{s_i}^{h}(x)\ \forall\ j\neq i.\label{eq:SD_constraints}
\end{align}
We refer to the solving of all subproblems $\left\{\left(P_i^\S\right)\right\}_{i=1}^k$ as a \textit{Survey Descent iteration}.
\end{defn}

When $\left(P_i^\S\right)$ is feasible, we denote its optimal solution as $s_i^+$. When all subproblems are feasible, we say that the entire Survey Descent iteration is \textit{feasible} and call $\S^+=\left\{s_i^+\right\}_{i=1}^k$ the \textit{outputs} of the iteration; otherwise, we say the entire iteration is \textit{infeasible}. After a feasible iteration, we would update $\S{\leftarrow}\S^{+}$ and repeat the Survey Descent iteration on the updated survey.


\begin{equation}
    \bx = \arg\min_{x \in \R^n} f(x) \text{ and } 0\in\Relint\left( \partial f(\bx) \right),\label{eq:nondegen}
\end{equation}

where $\Relint(\cdot)$ denotes the relative interior. We further assume the following structure around $\bx$.
\begin{defn}\label{def:strong_max}
A function $f:\R^n \to \R$ is a \textit{strong $\C^2$ max function} if it is locally expressible near $\bx$ as\begin{equation}\label{eq:f_objective}
f\left(x\right)=\underset{i=1,...k}{\max}f_{i}\left(x\right),
\end{equation}
where $k$ is some finite number, the \textit{components} $\left\{f_i\right\}_{i=1}^k$ are $\C^2$-functions satisfying $f_i(\bx)=f(\bx)$ for all $i$, their gradients $\left\{\nabla f_i(\bx)\right\}_{i=1}^k$ are affinely independent, and their Hessians $\nabla^2 f_i (\bx)$ are positive definite. As a consequence, there exists constants $\delta,L>0$ such that their Hessians satisfy\begin{equation}
    \delta I \preceq \nabla^2 f_i(x) \preceq L I \ \forall \ i=1,\dots,k, \label{eq:hessian}
\end{equation} 
for $x$ near $\bx$---where $I$ is the $n{\times}n$ identity matrix.
\end{defn}

Our analysis in this paper is entirely local, but we \underline{assume for the rest of this paper} that $f$ is a strong $\C^2$ max function with nondegenerate minimizer $\bx$. For simplicity, we also assume that the properties in Definition \ref{def:strong_max} hold \textit{globally} for all $x\in \R^n$. In this setting, we refer to $k$---which is necessarily unique---as the \textit{degree} of $f$. Moreover, note that \eqref{eq:hessian} implies all components $\left\{f_i\right\}_{i=1}^k$ are $L$-smooth, both $f$ and its components are $\delta$-strongly convex, and $\bx$ is $f$'s \textit{unique} minimizer. 

To study Survey Descent (Definition \ref{def:SD_Method}) on the objective $f$, we choose the above-presented $L$ as the step-control parameter and define the following notions of \textit{valid} and \textit{minimizing} surveys.


\begin{defn}
\textbf{\label{def:validS} ($\S, \bX$-Surveys and Validity)} For the objective $f$, define a \textit{survey} as a matrix $\S \equiv \left[s_{1}{,}\dots{,}s_{k}\right] \in \mathbb{\R}^{n\times k}$ consisting of $k$ columns\footnote{We can equivalently consider $\S$ as a set $\{s_i\}_{i=1}^k$. We will use the matrix and set interpretations interchangeably.} (the ``survey points''), where $k$ is the degree of $f$; \textit{valid surveys} as surveys satisfying $f_{i}\left(s_{i}\right){>}f_{j}\left(s_{i}\right)$ for all $i{\neq}j$; and the \textit{minimizing survey} as $\bX \equiv [\bx{,}\dots{,}\bx]$ whose survey points are all equal to $\bx$.
\end{defn}

\begin{equation}
\left\| \S\right\| \equiv\left\| \left[s_{1},\dots,s_{k}\right]\right\| _{2,\infty}=\max_{i=1,\dots,k}\left\| s_{i}\right\| _{2},\label{eq:surv_norm}
\end{equation}

Given a valid $\S$ sufficiently close to $\bX$, Survey Descent exhibits many desirable properties when minimizing $f$. As a preliminary, note that \eqref{eq:nondegen} and Definition \ref{def:strong_max} implies there exists unique \textit{critical weights} $\left\{ \blam_{i}\right\}_{i=1}^{k}{>}0$ such that 
\begin{align}
\sum_{i=1}^{k}\blam_{i} & =1,\label{eq:lam_sum1}\\
\sum_{i=1}^{k}\blam_{i}\nabla f_{i}(\bx) & =0.\label{eq:lam_sum0}
\end{align}

As we will see, the Lagrange multipliers of Survey Descent subproblems will lie ``close'' to $\left\{ \blam_{i}\right\}_{i=1}^{k}{>}0$, while the subproblem outputs $\left\{s_i^+\right\}_{i=1}^k$ will lie near  $\bx$. To characterize the order-of-magnitude of these distances, we adopt the ``Big-Oh'' notation. In particular, for a mapping $g:\mathbf{E}{\to}\F$ between two Euclidean spaces and letting $\left\| \cdot\right\|^p$ denote an arbitrary Euclidean norm raised to the $p$-th power, we use the notation 
$g\left(x\right)=O\left(\left\| x\right\| ^{p}\right)$
to indicate the property that there exists a constant $K{>}0$ such that $ \left\| g\left(x\right)\right\|{\leq}K\left\| x\right\| ^{p}$ holds for all small $x$. By itself, we let $\mathrm{O}\left(\left\| x\right\| ^{p}\right)$ denote an element of the class of all functions with this property.


\begin{setting} \label{setting:localSD} \textbf{(Local Analysis of Survey Descent)}
Consider an iteration of Survey Descent on a strong $\C^2$ max function objective, $f$, with a survey 
$\S$ that is valid and sufficiently close to $\bX$. For $i{=}1{,}\dots{,}k$, denote the output of the $i$-th Survey Descent subproblem by $s_i^+$.
\end{setting}


\begin{equation}\label{eq:valS}
\nabla f\left(s_{i}\right)=\nabla f_{i}\left(s_{i}\right) \ \forall \ i=1,\dots,k,
\end{equation}

\begin{observe}
\textbf{(Survey Descent Iterations on Max-of-Smooth Objectives)\label{obs:SD_MOS}} Assume that $\S$ is a valid survey for the objective $f$. Then, for all $i$, the $i$-th subproblem $\left(P_{i}^{\S}\right)$ of Survey Descent (Definition \ref{def:SD_Method}) is equivalent to \begin{equation}\begin{aligned}\min_{x}\ & \left\| x-\left(s_{i}-\frac{1}{L}\nabla f_{i}\left(s_{i}\right)\right)\right\| _{2}^{2}\\
\mathrm{s.t.}\ & \ell_{s_j}^{f_j}(x)+\frac{L}{2}\left\| x-s_{j}\right\| _{2}^{2}\leq \ell_{s_i}^{f_i}(x)\ \forall\ j\neq i.
\end{aligned}
\label{eq:raw_form_analytic}
\end{equation}
\end{observe}


\begin{align}
\U & \equiv \bx + \Span\left\{ \nabla f_{i}(\bx)-\nabla f_{j}(\bx):1\leq i,j\leq k\right\} ^{\perp} \label{eq:Udef1}\\
 & = \bx +  \left\{ \sum_{i}^k\gamma_{i}\nabla f_{i}(\bx):\sum_{i}^k\gamma_{i}=0\right\} ^{\perp} \label{eq:Udef2}\\
 & = \bx +  \left\{x\in \R^n: \ \nabla f_i(\bx)^T x = \nabla f_j(\bx)^T x \ \forall \ 1\leq i,j\leq k\right\}.\label{eq:Udef3}
\end{align}

\begin{equation}
    a_i \equiv \nabla f_i(\bx) \text{ and } A_i \equiv \nabla^2 f_i(\bx) \ \forall \  i=1,\dots,k. \label{eq:A_notation}
\end{equation}

\begin{equation}
    f_{i}\left(x\right)= f(0) + a_{i}^{T}x+\frac{1}{2}x^{T}A_{i}x+r_{i}\left(x\right) \ \forall \ i=1,\dots,k,\label{eq:taylor}
\end{equation}

where $r_i(x)$ is a residual function.


\begin{equation}
    \blam_{\min} \equiv \min_{i=1,\dots,k} \blam_{i} > 0. \label{eq:min_lam}
\end{equation}

\begin{procedure}\textbf{(Repeated Iterations of Survey Descent) }\label{procedure:SD}
For the strong $\C^2$ max function objective $f$, assume $\S^{0}$ is a valid initial survey sufficiently close to $\bX$, and initialize $t=0$. Iterate the following steps:
\begin{enumerate}
\item Solve the Survey Descent iteration $\left\{ \left(P_{i}^{\S^{t}}\right)\right\} _{i=1}^{k}$
and denote the output $\S^{t+1}\equiv\left(\S^{t}\right)^{+}$.
\item Increment $t\leftarrow t+1$. 
\end{enumerate}
\end{procedure}


\begin{observe}\label{obs:allT}
The proof of Corollary \ref{cor:viable} more generally shows that, for all $t \in \nonneg$, all surveys $\S^{t}$ will remain sufficiently close to $\bX$. Thus, the conclusions from Theorems \ref{thm:SD_MBP}-\ref{thm:s_monotone} apply to every iteration of Procedure \ref{procedure:SD}.
\end{observe}


\begin{defn}
    \textbf{(Multiple Balls Problem, $\MBP\param$)\label{def:MBP}} \sloppy For some
    target vector $y\in\R^{n}$, ball centers $Z=\left[z_{1},\dots,z_{\bk}\right]\in\R^{n\times\bk}$
    where $\bk\leq n$, and non-negative radii $r=\left[r_{1},\dots,r_{\bk}\right]^{T}\in\R^{\bk}_{+}$,
    define the \textit{Multiple Balls Problem (MBP)} as 
    \begin{align}
    \min_{x\in\R^{n}}\ & \left\| x-y\right\| _{2}^{2} \nonumber\\
    \mathrm{s.t.}\ & \left\| x-z_{j}\right\| _{2}^{2} = r_{j}^{2}\ \forall\ j=1,\dots,\bk. \label{eq:MBP_cons}
    \end{align}
    Denote the problem as $\MBP\param$ and its \textit{feasible region} as $\B\spec$. We will refer to the tuple $\param$ as the \textit{parameters} and the sub-tuple $\spec$ as the \textit{ball-specifications} of the MBP.
    \end{defn}

    Since $y$, $Z$, and $r$ all reside in Euclidean spaces, we can also consider $\spec$ and $\param$ elements of some product space. Let $\left\Vert \cdot\right\Vert $ denote an arbitrary Euclidean norm. This will allow us to formalize the notion of distance in of parameters and ball-specifications in their respective spaces. We are particularly interested in the behavior of $\MBP\param$ where $\param$ is near some set of \textit{base parameters}.


\begin{defn}
    \textbf{(Base Parameters)\label{def:base}} We refer to a set of parameters
    as \textit{base parameters} and denote them as $\bparam$
    if they satisfy the following properties:
    \begin{itemize}
    \item The columns of $\bZ=\left[\bz_{1},\dots,\bz_{\bk}\right]$ are linearly
    independent.
    \item $\br_{j}^{2}=\left\| \bz_{j}\right\| _{2}^{2}$.
    \item There exist strictly-positive weights $\clam=\left[\clam_{1},\dots,\clam_{\bk}\right]^{T}\in\R_{++}^{\bk}$
    such that $\bar{y}=-\sum_{j=1}^{\bk}\clam_{j}\bar{z}_{j}.$
    \end{itemize}
    \end{defn}

    \begin{itemize}
        \item The \textit{central affine subspace}
            \begin{equation}
            \A\spec \equiv \left\{ x\in\R^{n}:\ 2z_{j}^{T}x-\left\| z_{j}\right\| _{2}^{2}+r_{j}^{2}\text{ equal  for all } j=1,\dots,\bk\right\}. \label{eq:CAS}
            \end{equation}
        \item The \textit{core}
            \begin{equation}
            c\spec\equiv\projA{\spec}\left(z_{j}\right)\ \text{ for any }\ j=1,\dots,\bk, \label{eq:core}
            \end{equation}
            where $\projA{\spec}$ denotes the projection onto $\A\spec$.
        \item The \textit{margin}
            \begin{equation}
            \rho\spec\equiv\sqrt{r_{j}^{2}-\left\| z_{j}-c\spec\right\| _{2}^{2}} \ \text{ for any }\ j=1,\dots,\bk. \label{eq:margin}
            \end{equation}
    \end{itemize}


    In this section, we will show that the optimal solutions of MBPs are unchanged when the equality constraints \eqref{eq:MBP_cons} are relaxed to inequalities. In particular, regardless of whether $\MBP\param$ is defined with equality or inequality constraints, note that the stationarity conditions remain the same. Therefore, there must exist some Lagrange multipliers, $\lambda\param\in\R^m$, such that\begin{equation}
    x\param-y+\sum_{j=1}^{\bk}\lambda_{j}\param\left[x\param-z_{j}\right]=0, \label{eq:MBP_FOC}
    \end{equation}
    where $\lambda_{j}\param$ denotes the $j$-th element of $\lambda\param$. The only difference is that the inequality version possesses additional dual feasibility conditions requiring the non-negativity of $\lambda\param$. Lemma \ref{lem:MBP_lam} will show that the $\lambda\param$ are unique and strictly positive.


    We can reformulate Survey Descent subproblems into inequality-constrained MBPs. In particular, for all $i$, we can rewrite the $i$-th Survey Descent subproblem in Observation \ref{obs:SD_MOS} as



\begin{gather}\begin{aligned}\min_{x}\ & \left\| (x - s_{i}) - y_{i}\left(\S\right) \right\| _{2}^{2}\\
    \mathrm{s.t.}\ & \left\| (x-s_{i})-z_{ij}\left(\S\right)\right\| _{2}^{2}\leq r_{ij}^{2}\left(\S\right)\ \forall\ j\neq i,
    \end{aligned}
    \label{eq:proj_form}
    \end{gather}

    where, for all $i$ and $j$, we define the following mappings using the components $\{f_i\}_{i=1}^k$ from Definition \ref{def:strong_max}:



\begin{gather}\begin{aligned}
    y_{i}\left(\S\right)& \equiv-\frac{1}{L}\nabla f_{i}\left(s_{i}\right),\\
    z_{ij}\left(\S\right) & \equiv s_j - s_i  + y_{j}\left(\S\right)-y_{i}\left(\S\right),\\
    r_{ij}^{2}\left(\S\right) & \equiv\frac{2}{L}\left[f_{i}\left(s_{i}\right)-f_{j}\left(s_{j}\right)+\nabla f_{i}\left(s_{i}\right)^{T}\left(s_{j}-s_{i}\right)\right]+\left\|y_{j}\left(\S\right)-y_{i}\left(\S\right)\right\| _{2}^{2}.
    \end{aligned}\label{eq:MBP_mappings}
    \end{gather}

    \begin{observe}\textbf{(Survey Descent as Inequality-Constrained MBP)} \label{obs:SD_as_MBP} Consider any $k$-point survey $\S$ and any $i{=}1,\dots,k$. After the changes-of-variables $x \leftarrow x{-} s_i$, the minimization problem in \eqref{eq:proj_form} is an inequality-constrained MBP  with $\m = k{-}1$ and parameters 

    $$\param = \left(y_{i}\left(\S\right), \left[ z_{ij}\left(\S\right)\right]_{j\neq i}, \left[r_{ij}\left(\S\right)\right]_{j\neq i},\left[ s_{j}\right]_{j\neq i}\right),$$
    where, for any $j$-indexed scalars $\left\{v_j\right\}_{j=1}^{k}$, we use the notation $\left[v_j\right]_{j \neq i}{\equiv} \left[v_1,\dots,v_{i-1},v_{i+1},\dots,v_{k}\right]^T$ to denote the length $k{-}1$ vector excluding $v_i$.
    Furthermore, the mappings \eqref{eq:MBP_mappings}  evaluated at the base survey\footnote{Evaluating of the mappings \eqref{eq:MBP_mappings} at $\bX$ is a technical step. $\bX$ is not a valid survey (Definition \ref{def:validS}), so it does not correspond to an actual Survey Descent iteration.} $\bX$ (Definition \ref{def:validS}) form a set of base parameters
    \begin{equation}
        \bparam = \left(y_{i}\left(\bX\right), \left[ z_{ij}\left(\bX\right)\right]_{j\neq i}, \left[r_{ij}\left(\bX\right)\right]_{j\neq i}, [\bx]_{j\neq i}\right),\label{eq:MBP_SD_base}
    \end{equation}
    with corresponding weights $\{\blam_j\}_{j\neq i}$ from \eqref{eq:lam_sum1}-\eqref{eq:lam_sum0}, and where $[\bx]_{j\neq i}$ is the $k{-}1$ length vector with all $\bx$ entries.
    \end{observe}

