\begin{restatable}{thm}{PBmbp}\label{thm:SD_MBP} \textbf{(Local Feasibility, Uniqueness, Tightness, and Smoothness of Survey Descent)} Assume Setting \ref{setting:localSD}. Then for all $i$, the Survey Descent subproblem $\left(P_{i}^{\S}\right)$ is feasible and has a unique solution $s_{i}^{+}$, which satisfies all the constraints with equality, with unique associated Lagrange multipliers $\lambda_{j}^i$ \edit{for the $j$-th constraint within the $i$-th subproblem}  (for $j\neq i$). The solutions and multipliers depend smoothly on the input survey $\S$, and satisfy\begin{equation}
s_{i}^{+}\left(\S\right) ~=~\bx+\mathrm{O}\left(\left\| \S-\bX\right\| \right) \qquad \text{and} \qquad \lambda_{j}^i\left(\S\right) ~=~ \blam_{j}+\mathrm{O}\left(\left\| \S-\bX\right\| \right)\ \forall\ j\neq i.\label{eq:SD_forms}
\end{equation}
\end{restatable}

\begin{proof}
Follows from a routine analysis of the subproblem's first-order optimality conditions combined with the implicit function theorem.
\end{proof}

\begin{proof}
Consider any fixed $i$. If $s_{i}^{+}=s_{i}$, then the fact
that $f_{i}\left(s_{i}^{+}\right){>}f_{j}\left(s_{i}^{+}\right)$ for all $j\neq i$ immediately follows since Theorem \ref{thm:SD_MBP} assumes $\S$ is valid.

Now, consider the $s_{i}^{+}{\neq}s_{i}$ case. By Theorem \ref{thm:SD_MBP}, $s_{i}^{+}$ satisfies the constraints of $\left(P_{i}^{\S}\right)$ with equality. Using Observation \ref{obs:SD_MOS}, we express this as\begin{equation}
\ell_{s_i}^{f_i}(s_i^+) = \ell_{s_j}^{f_j}(s_i^+)+\frac{L}{2}\left\| s_{i}^{+}-s_{j}\right\|_{2}^{2}\ \forall\ j\neq i.\label{eq:left_valid}
\end{equation}
The $\delta$-strong convexity of $f_{i}$ implies
\begin{equation*}
f_{i}\left(s_{i}^{+}\right)\geq\ell_{s_i}^{f_i}(s_i^+)+\frac{\delta}{2}\left\| s_{i}^{+}-s_{i}\right\| _{2}^{2}>\ell_{s_i}^{f_i}(s_i^+),
\end{equation*}
where the strict inequality follows from $s_{i}^{+}{\neq}s_{i}$. Next, by the $L$-smoothness of $\left\{f_j\right\}_{j=1}^k$, the right-hand side of \eqref{eq:left_valid} is a $s_j$-centered quadratic upper bound of $f_{j}$ evaluated at $s_i^+$. Thus,
\begin{equation*}
\ell_{s_j}^{f_j}(s_i^+)+\frac{L}{2}\left\| s_{i}^{+}-s_{j}\right\|_{2}^{2} \geq f_{j}\left(s_{i}^{+}\right) \ \forall\ j\neq i.
\end{equation*}

\noindent Therefore, 
\begin{equation*}
f_{i}\left(s_{i}^{+}\right) > \ell_{s_i}^{f_i}(s_i^+) = \ell_{s_j}^{f_j}(s_i^+)+\frac{L}{2}\left\| s_{i}^{+}-s_{j}\right\|_{2}^{2} \geq f_{j}\left(s_{i}^{+}\right) \ \forall\ j\neq i.
\end{equation*}
This completes the proof.
\end{proof}

\begin{lem}
\label{lem:r_grad} For all $i$, the residual function $r_i(x)$ in \eqref{eq:taylor} satisfies $r_i(x)=\mathrm{O}\left(\|x\|^2\right)$ and $\nabla r_{i}\left(x\right)=\mathrm{O}\left(\left\| x\right\|\right)$.
\end{lem}

\begin{proof}
$r_i(x)=\mathrm{O}\left(\|x\|^2\right)$ follows directly from Taylor's Theorem. Next, observe that 
\begin{equation*}
    r_{i}\left(x\right)=f_{i}\left(x\right)-\left(f(0) + a_{i}^{T}x+\frac{1}{2}x^{T}A_{i}x\right).
\end{equation*}
Thus, since $f_i$ is $\C^2$, the residual $r_i$ must also be $\C^2$, so its gradient and Hessian are well-defined. This implies $\nabla r_{i}\left(x\right)$ is then $\C^{1}$. Taylor expanding $\nabla r_i$ around zero then gives the desired $\nabla r_{i}\left(x\right)= \mathrm{O}\left(\| x\|\right)$
after observing that $\nabla r_i(0)$ is the zero-vector and $\nabla^2 r_i(0)$ is the zero-matrix (since $r_i$ is the residual of the Taylor expansion of $f_i$ around zero).
\end{proof}

\begin{lem}\label{lem:U_component} Assume Setting \ref{setting:localSD} and suppose $\bx{=}0$. Then, $s_{i}^{+}$ satisfies
\begin{equation*}
\proj\left[s_{i}^{+}\right]=\frac{1}{2-\blam_{i}}\proj\left[s_{i}-\frac{\blam_{i}}{L}\nabla f_{i}\left(s_{i}\right)\right]+\sum_{j\neq i}\frac{\blam_{j}}{2-\blam_{i}}\proj\left[s_j - \frac{1}{L} \nabla f_j(s_j)\right]+\mathrm{O}\left(\left\| \S\right\| ^{2}\right) \ \forall \ i=1,\dots,k.
\end{equation*}
where $\proj$ is the projection operator onto the $\U$-subspace \eqref{eq:Udef1}.
\end{lem}

\begin{proof}
Without loss of generality, assume $i=k$. Scale the objective of problem \eqref{eq:raw_form_analytic} by $\frac{L}{2}$ and consider the equivalent problem
\begin{equation}\begin{aligned}\min_{x}\ & \frac{L}{2} \left\| x-\left(s_{k}-\frac{1}{L}\nabla f_{k}\left(s_{k}\right)\right)\right\| _{2}^{2}\\
\mathrm{s.t.}\ & \ell_{s_j}^{f_j}(x)+\frac{L}{2}\left\| x-s_{j}\right\| _{2}^{2}\leq \ell_{s_k}^{f_k}(x)\ \forall\ j\neq k.
\end{aligned}\label{eq:scaledPk}
\end{equation}
By Theorem \ref{thm:SD_MBP} and Observation \ref{obs:SD_MOS}, there exists unique Lagrange multipliers $\left\{\lambda_j\right\}_{j=1}^{k-1}$ (we omit the $k$-superscript for simplicity) satisfying the following first-order optimality condition for \eqref{eq:scaledPk}:
$$
    0=L\left(s_{k}^{+}-\left(s_{k}-\frac{1}{L} \nabla f_{k}\left(s_{k}\right)\right)\right)+\sum_{j=1}^{k-1} \lambda_{j}\left(\edit{\nabla f_{j}\left(s_{j}\right)}+L\left(s_{k}^{+}-s_{j}\right)-\nabla f_{k}\left(s_{k}\right)\right)
    $$
After rearranging this gives\begin{equation}
0= L\left(1+\sum_{j=1}^{k-1}\lambda_{j}\right)s_{k}^{+}-L\left(s_{k} + \sum_{j=1}^{k-1} \lambda_{j} s_{j}\right)+\nabla f_k(s_k) +\sum_{j=1}^{k-1}\lambda_{j}\left(\nabla f_j(s_j) - \nabla f_k(s_k)\right).
\label{eq:FOC2}
\end{equation}
Define the following scalars:
\begin{align}
    \lambda_{k} & \equiv  1-\sum_{j=1}^{k-1}\lambda_{j},\label{eq:lambda}\\
    \mu_{j} & \equiv  \blam_{j}-\lambda_{j} \ \forall \ j=1,\dots,k. \label{eq:mu}
\end{align}
For $j\neq k$, Theorem \ref{thm:SD_MBP} gives
$\mu_{j}=\mathrm{O}\left(\left\| \S\right\| \right)$ .
For $j=k$, combining \eqref{eq:lambda}-\eqref{eq:mu} with equation \eqref{eq:lam_sum1} implies
\begin{equation*}
\mu_{k} =\blam_{k}-\left(1-\sum_{j=1}^{k-1}\lambda_{j}\right) =\blam_{k}-\left(1-\sum_{j=1}^{k-1}\blam_{j}\right)+\mathrm{O}\left(\left\| \S\right\| \right) =\mathrm{O}\left(\left\| \S\right\| \right).
\end{equation*}
Thus,\begin{equation}
    \mu_j = \mathrm{O}(\|\S\|) \ \forall \ j=1,\dots,k.\label{eq:mu_size}
\end{equation}
Substituting \eqref{eq:mu} into \eqref{eq:FOC2}, applying identities \eqref{eq:lam_sum1}-\eqref{eq:lam_sum0}, collecting $\mathrm{O}\left(\|\S\|^2\right)$ terms, and solving for $s_k^{+}$ gives\begin{equation}s_{k}^{+}= \frac{1}{2-\blam_{k}}\left[s_{k}-\frac{\blam_{k}}{L}\nabla f_{k}\left(s_{k}\right)\right]+\sum_{j=1}^{k-1}\frac{\blam_{j}}{2-\blam_{k}}\left[s_j - \frac{1}{L} \nabla f_j(s_j)\right]+\frac{1}{L\left(2-\blam_{k}\right)}\sum_{j=1}^{k}\mu_{j}\nabla f_j(s_j) +\mathrm{O}\left(\left\| \S\right\| ^{2}\right).\label{eq:pre_sform}
\end{equation}
Adopting the notation \eqref{eq:A_notation} and applying the Taylor expansion \eqref{eq:taylor}, observe\begin{equation}
    \sum_{j=1}^{k}\mu_{j}\nabla f_j(s_j) = \sum_{j=1}^{k}\mu_{j}\left(a_j + A_j s_j + \nabla r_j (s_j)\right) = \sum_{j=1}^{k}\mu_{j}a_j +\mathrm{O}\left(\left\| \S\right\|^{2}\right),\label{eq:sum_muA}
\end{equation}
where last equality follows from \eqref{eq:mu_size} and Lemma \ref{lem:r_grad}. Substituting \eqref{eq:sum_muA} into \eqref{eq:pre_sform} then leads to\begin{equation}
s_{k}^{+}=\frac{1}{2-\blam_{k}}\left[s_{k}-\frac{\blam_{k}}{L}\nabla f_{k}\left(s_{k}\right)\right]+\sum_{j=1}^{k-1}\frac{\blam_{j}}{2-\blam_{k}}\left[s_j - \frac{1}{L} \nabla f_j(s_j)\right]+\frac{1}{L\left(2-\blam_{k}\right)}\underbrace{\sum_{j=1}^{k}\mu_{j}a_j}_{(\star)} +\mathrm{O}\left(\left\| \S\right\| ^{2}\right).
\label{eq:s_form}
\end{equation}
Next, again combine \eqref{eq:lambda}-\eqref{eq:mu} with equation \eqref{eq:lam_sum1} to deduce
\begin{equation*}
\sum_{j=1}^{k}\mu_{j}=\sum_{j=1}^{k}\left(\blam_{j}-\lambda_{j}\right)=0.
\end{equation*}
Then, it follows from \eqref{eq:Udef2} that $\proj\left[(\star)\right]=0$.
The desired result then follows from applying $\proj$ to \eqref{eq:s_form}.
\end{proof}

\begin{lem}\label{lem:Up_component}
Assume Setting \ref{setting:localSD}, and let $\bx{=}0$. Then, $s_{i}^{+}$ satisfies
\begin{equation*}
\projp\left[s_{i}^{+}\right]=\mathrm{O}\left(\left\| \S\right\| ^{2}\right) \ \forall \ i=1,\dots,k.
\end{equation*}
where $\projp$ is the projection operator onto the orthogonal complement of the $\U$-subspace \eqref{eq:Udef1}.
\end{lem}

\begin{proof}
Consider any fixed $i$. By Theorem \ref{thm:SD_MBP}, the constraints of $\left(P_{i}^{\S}\right)$
are tight. Thus, by Observation \ref{obs:SD_MOS}, $s_{i}^{+}$ satisfies
\begin{equation*}
    f_{j}\left(s_{j}\right)+\nabla f_{j}\left(s_{j}\right)^{T}\left(s_i^+-s_{j}\right)+\frac{L}{2}\left\| s_i^+-s_{j}\right\| _{2}^{2} = f_{i}\left(s_{i}\right)+\nabla f_{i}\left(s_{i}\right)^{T}\left(s_i^+-s_{i}\right) \ \forall \ j\neq i.
\end{equation*}
Using equation \eqref{eq:taylor} in the above gives, for all $j\neq i$,
\begin{multline*}
    f(0) + a_{j}^{T}s_{j}+\frac{1}{2}s_{j}^{T}A_{j}s_{j}+r_{j}\left(s_j\right)+\left(a_{j}+A_{j}s_{j} + \nabla r_j(s_j)\right)^T\left(s_{i}^{+}-s_{j}\right)+\frac{L}{2}\left\Vert s_{i}^{+}-s_{j}\right\Vert _{2}^{2}\\
    =f(0) + a_{i}^{T}s_{i}+\frac{1}{2}s_{i}^{T}A_{i}s_{i}+r_{i}\left(s_i\right)+\left(a_{i}+A_{i}s_{i}+\nabla r_i(s_i)\right)^T\left(s_{i}^{+}-s_{i}\right).
\end{multline*}
After simplification and rearrangement, we obtain\begin{equation}
\left(a_{j}-a_{i}\right)^{T}s_{i}^{+}=-\left(A_{j}s_{j}-A_{i}s_{i}+\nabla r_{j}\left(s_{j}\right)-\nabla r_{i}\left(s_{i}\right)\right)^{T}s_{i}^{+}-\frac{L}{2}\left\| s_{i}^{+}-s_{j}\right\| _{2}^{2}-c_{j}\left(s_{j}\right)+c_{i}\left(s_{i}\right)  \ \forall \ j\neq i, \label{eq:s_constr}
\end{equation}
where we define the functions
\begin{equation*}
c_{j}\left(x\right)\equiv-\frac{1}{2}x^{T}A_{j}x+r_{j}\left(x\right)-\nabla r_{j}\left(x\right)^{T}x \ \forall \ j=1,\dots,i.
\end{equation*}
By Lemma \ref{lem:r_grad}, $c_j(x)$ is $O\left(\|x\|^2\right)$. Since we assume $\bx{=}0$, by Theorem \ref{thm:SD_MBP}, $s_{i}^{+}=\mathrm{O}\left(\left\| \S\right\| \right)$.
We then deduce that all terms on the right-hand side of \eqref{eq:s_constr} are $\mathrm{O}\left(\left\| \S\right\|^2 \right)$:
\begin{equation}
\left(a_{j}-a_{i}\right)^{T}s_{i}^{+}=\mathrm{O}\left(\left\| \S\right\|^2 \right) \ \forall \ j\neq i.\label{eq:projsp}
\end{equation}
% Consider the following $QR$-decomposition 
% \[
% \begin{bmatrix}\left(a_{1}-a_{i}\right), & \dots, & \left(a_{i-1}-a_{i}\right)\end{bmatrix}\equiv\bQ\bR,
% \]
% where $\bQ\in\R^{n\times\left(k-1\right)}$ is an orthonormal matrix,
% and $\bR\in\R^{\left(k-1\right)\times\left(k-1\right)}$ is an upper-triangular
% matrix. Then,
% \begin{equation}
% \bR^{T}\bQ^{T}s_{i}^{+}=\mathrm{O}\left(\left\| \S\right\| ^{2}\right).\label{eq:s_constr2}
% \end{equation}
By \eqref{eq:Udef1},
\begin{align*}
\U^{\perp} & =\Span\left\{ a_{i}-a_{j}:1\leq i,j\leq k\right\} =\Span\left\{ a_{j}-a_{i}:\ j \neq i \right\}.
\end{align*}
Combined with the affine independence of $\left\{ a_{j}\right\} _{j=1}^{k}$
(Definition \ref{def:strong_max}), the above implies $\left\{ a_{j}-a_{i}\right\} _{j\neq i}$ forms a basis for $\U^{\perp}$. Therefore, we can express the projection onto $\U^{\perp}$ in terms $\left\{ a_{j}-a_{i}\right\} _{j\neq i}$. The result now follows from equation \eqref{eq:projsp} and standard linear algebra.
% Thus, $\bR$ is invertible,
% and we can represent the projection onto $\U^{\perp}$ as multiplication by the matrix $\bQ\bQ^{T}.$ From this, we deduce
% \begin{equation*}
% \projp\left[s_{i}^{+}\right]=\bQ\bQ^{T}s_{i}^{+}=\bQ\left(\bR^{T}\right)^{-1}\bR^{T}\bQ^{T}s_{i}^{+}=\mathrm{O}\left(\left\| \S\right\| ^{2}\right),
% \end{equation*}
% where the last equality follows from \eqref{eq:s_constr2} and the
% fact that $\bQ\left(\bR^{T}\right)^{-1}$ is a constant-matrix independent
% of $\S$.
\end{proof}

\begin{thm}
\label{thm:approx_s} \textbf{(Gradient Descent Approximation of Survey Updates)} Assume Setting \ref{setting:localSD}.  Then the solution of the $i$-th Survey Descent subproblem satisfies, for all $i$, \begin{equation}
s_{i}^{+}= \ts_{i}+\mathrm{O}\left(\left\| \S - \bX\right\| ^{2}\right) \label{eq:SD_iter}
\end{equation}
where we define\begin{equation}
\ts_{i}\equiv\frac{1}{2-\blam_{i}}\proj\left[s_{i}-\frac{\blam_{i}}{L}\nabla f_{i}\left(s_{i}\right)\right]+\sum_{j\neq i}\frac{\blam_{j}}{2-\blam_{i}}\proj\left[s_j - \frac{1}{L} \nabla f_j(s_j)\right], \label{eq:s_tilde}
\end{equation}
and $\proj$ is the projection operator onto the $\U$-subspace \eqref{eq:Udef1}.
\end{thm}

\begin{proof}
Without loss of generality, assume that $\bx{=}0$. Then, the desired result follows from decomposing $s_{k}^{+} = \proj\left[s_{k}^{+}\right] + \projp\left[s_{k}^{+}\right]$ and applying Lemmas \ref{lem:U_component} and \ref{lem:Up_component}. We can deduce the general $\bx{\neq}0$ case with the change of variables $x{\leftarrow}(x-\bx)$.
\end{proof}

\begin{thm}
\textbf{\label{thm:PR}(Projected-GD Behavior)} Assume that $\S$ is a valid survey for the strong $\C^2$ max function objective $f$. Then, the following holds for all $i$ and any constant $\tL \geq L$:
\begin{align*}
\left\| \proj\left[s_i - \frac{1}{\tL} \nabla f_i(s_i)\right] - \bx\right\| _{2}^{2} &\leq \left(1-\frac{\delta}{\tL}\right)\left\| s_{i} - \bx \right\| _{2}^{2},\\
f_{i}\left(\proj\left[s_i - \frac{1}{\tL} \nabla f_i(s_i)\right]\right) - f_i(\bx) &\leq \frac{\tL}{2}\left(1-\frac{\delta}{\tL}\right)\left\| s_{i} - \bx\right\| ^{2}.
\end{align*}
\end{thm}

\begin{proof}
Consider any fixed $i$. It is easy to check that $\bx = \arg\min_{x \in \U} f_i(x)$ using first-order optimality conditions combined with \eqref{eq:lam_sum1}-\eqref{eq:lam_sum0} and \eqref{eq:Udef3}. The desired result then follows from classical projected-GD convergence results (given in standard texts such as \citet[Theorem 10.29]{beck2017}) after observing that $\U$ is convex and $f_i$ is $L$-smooth and $\delta$-strongly convex.
\end{proof}

\begin{lem}
\label{lem:st_bound} Assume Setting \ref{setting:localSD}, and suppose $\bx{=}0$. Then, the following must hold:
\begin{equation*}
\left\| \ts_{i}\right\| _{2}^{2}\leq\left(1-\frac{\blam_{\min}\delta}{L}\right)\max_{j=1,....,k}\left\| s_{j}\right\| _{2}^{2} \ \forall \ i=1,\dots,k,
\end{equation*}
where $\ts_i$ and $\blam_{\min}$ are as defined in equations \eqref{eq:s_tilde} and \eqref{eq:min_lam}, respectively.
\end{lem}

\begin{proof} Consider any fixed $i$. Then,
\begin{align*}
\left\| \ts_{i}\right\| _{2}^{2} & =\left\| \frac{1}{2-\blam_{i}}\proj\left[s_{i}-\frac{\blam_{i}}{L}\nabla f_{i}\left(s_{i}\right)\right]+\sum_{j\neq i}\frac{\blam_{j}}{2-\blam_{i}}\proj\left[s_j - \frac{1}{L} \nabla f_j(s_j)\right] \right\| _{2}^{2}  \text{ (Substitute \eqref{eq:s_tilde})}\\
 & \leq\frac{1}{2-\blam_{i}}\left\| \proj\left[s_{i}-\frac{\blam_{i}}{L}\nabla f_{i}\left(s_{i}\right)\right]\right\| _{2}^{2}+\sum_{j\neq i}\frac{\blam_{j}}{2-\blam_{i}}\left\| \proj\left[s_j - \frac{1}{L} \nabla f_j(s_j)\right]\right\| _{2}^{2}\text{ (Convexity)}\\
 & \leq\frac{1}{2-\blam_{i}}\left(1-\frac{\blam_{i}\delta}{L}\right)\left\| s_{i}\right\| _{2}^{2}+\left(1-\frac{\delta}{L}\right)\sum_{j\neq i}\frac{\blam_{j}}{2-\blam_{i}}\left\| s_{j}\right\| _{2}^{2} \text{ (Theorem \ref{thm:PR} where $\tL=\frac{L}{\blam_i}$)}\\
 & \leq\left(1-\frac{\blam_{i}\delta}{L}\right)\left[\frac{1}{2-\blam_{i}}\left\| s_{i}\right\| _{2}^{2}+\sum_{j\neq i}\frac{\blam_{j}}{2-\blam_{i}}\left\| s_{j}\right\| _{2}^{2}\right]\\
 & \leq\left(1-\frac{\blam_{\min}\delta}{L}\right)\max_{j=1,....,k}\left\| s_{j}\right\| _{2}^{2}.
\end{align*}
This completes the proof.
\end{proof}

\begin{thm} \textbf{(Survey-Norm Contraction)} \label{thm:s_monotone} Assume Setting \ref{setting:localSD}.  Then the following must hold:
\begin{equation*}
\max_{j=1,...,k}\left\| s_{j}^{+} - \bx \right\| _{2}^{2}\leq\left(1-\frac{\blam_{\min}\delta}{L}\right)\max_{j=1,...,k}\left\| s_{j} - \bx \right\| _{2}^{2}+\mathrm{O}\left(\left\| \S - \bX\right\|^{3}\right),
\end{equation*}
where $\blam_{\min}$ is defined as in \eqref{eq:min_lam}.
\end{thm}

\begin{proof}
Without loss of generality, assume $\bx = 0$. Consider any fixed $i$. By Lemma \ref{lem:st_bound}, $\ts_{i}=\mathrm{O}\left(\left\| \S\right\| \right)$. Then,\begin{align*}
\left\| s_{i}^{+}\right\| _{2}^{2} & =\left\| \ts_{i}+\mathrm{O}\left(\left\| \S\right\| ^{2}\right)\right\| _{2}^{2} \text{ (Theorem \ref{thm:approx_s})}\\
 & =\left\| \ts_{i}\right\| _{2}^{2}+2\left\langle \ts_{i},\mathrm{O}\left(\left\| \S\right\| ^{2}\right)\right\rangle +\mathrm{O}\left(\left\| \S\right\| ^{4}\right)\\
 & \leq\left(1-\frac{\blam_{\min}\delta}{L}\right)\max_{j=1,....,k}\left\| s_{j}\right\| _{2}^{2}+\mathrm{O}\left(\left\| \S\right\| ^{3}\right) \text{ (Lemma \ref{lem:st_bound})}.
\end{align*}
The right-hand side is independent of $i$, so taking the max over $i$ on the left-hand side leads to the desired result. We can deduce the general $\bx{\neq}0$ case with the change of variables $x{\leftarrow}(x-\bx)$.
\end{proof}

\begin{proof}
For $\S^{0}$ sufficiently close to $\bX$, Theorem \ref{thm:s_monotone} inductively implies that $\left\| \S^{t+1} - \bX \right\| <\left\| \S^{t} - \bX\right\| $ for all $t\in\nonneg$. In other words, output surveys will always move closer to $\bX$, and Theorem \ref{thm:SD_MBP} and \ref{thm:strictval} continue to hold for Survey Descent iterations $\left\{\left(P_{i}^{\S^{t}}\right)\right\}_{i=1}^{k}$ for all $t\in \nonneg$. Thus, Theorem \ref{thm:SD_MBP} implies the feasibility all Survey Descent iterations while Theorem \ref{thm:strictval} implies the validity of output surveys.
% The viability of implementing the consecutive Survey Descent iterations with only a first-order oracle on $f$ follows directly from Remark \ref{rem:SD_FOM} and Theorem \ref{thm:strictval}.
\end{proof}

\begin{proof}
By Theorem \ref{thm:s_monotone} and Observation \ref{obs:allT}, there exists $K>0$ such that
\begin{equation*}
\left\| \S^{t+1} - \bX \right\|^{2}\leq\left(1-\frac{\blam_{\min}\delta}{L}\right)\left\| \S^{t} - \bX \right\|^{2}+K\left\| \S^{t} - \bX \right\|^{3} \ \forall \ t\in \nonneg.
\end{equation*}
Corollary \ref{cor:viable} implies that $\S^t$ is a valid survey. By Definition \ref{def:validS}, $\bX$ is not a valid survey because $f_i(\bx){=}f_j(\bx)$ for all $i,j$. Thus, $\S^t {\neq}\bX$, so $\left\| \S^{t} - \bX \right\|^2$ is nonzero and we can divide both sides by it.  We deduce
\begin{equation*}
\frac{\left\| \S^{t+1} - \bX \right\|^{2}}{\left\| \S^{t} - \bX \right\| ^{2}}\leq\left(1-\frac{\blam_{\min}\delta}{L}\right)+K\left\| \S^{t} - \bX\right\|  \ \forall \ t\in \nonneg.
\end{equation*}
\sloppy \edit{For $\S^{0}$ sufficiently close to $\bX$, this inequality guarantees that $\left\| \S^{t}{-}\bX\right\|$ monotonically decreases with $t$ and, in particular, $\left\| \S^{t}{-}\bX\right\|{<}\frac{\blam_{\min}\delta}{LK}$ for all $t\in\nonneg$.} Thus, $\frac{\left\| \S^{t+1} - \bX \right\|}{\left\| \S^{t} - \bX\right\|}{<}1$ implying $\underset{t\to\infty}{\lim}\left\| \S^{t}{-}\bX\right\|{=}0$. Taking the lim-sup with $t{\to}\infty$ on both sides of the above inequality then gives the desired result.
\end{proof}

\begin{lem}\textbf{(Local Properties of the Central Affine Subspace)}\label{lem:A}
    For any ball-specifications $\spec$ sufficiently close to base ball-specifications $\bspec$, the following properties hold:
    \begin{enumerate}
        \item $\A\spec$ is non-empty with dimension $n{-}\bk{+}1$.
        \item For all $i\neq j$, the direction $(z_i - z_j)$ is orthogonal to the linear subspace parallel to $\A\spec$.
        \item For $w\in\R^n$, the projection $\projA{\spec}(w)$ is well-defined and varies smoothly with $\spec$ and $w$.
    \end{enumerate}
    \end{lem}

\begin{proof}
    Observe that we can rewrite \eqref{eq:CAS} as the following $\left(\bk{-}1\right){\times}n$ linear system:\begin{equation}
    \A\spec=\left\{ x\in\R^{n}:\ M\spec x=b\spec \right\} ,\label{eq:CAS_sys}
    \end{equation}
    where 
    \[
    M\spec\equiv2\begin{bmatrix}\left(z_{2}-z_{1}\right)^{T}\\
    \vdots\\
    \left(z_{\m}-z_{1}\right)^{T}
    \end{bmatrix}
    \text{ and }
    b\spec\equiv\begin{bmatrix}\left(\left\| z_{2}\right\| _{2}^{2}-r_{2}^{2}\right)-\left\| z_{1}\right\| _{2}^{2}+r_{1}^{2}\\
    \vdots\\
    \left(\left\| z_{\bk}\right\| _{2}^{2}-r_{\bk}^{2}\right)-\left\| z_{1}\right\| _{2}^{2}+r_{1}^{2}
    \end{bmatrix}.\
    \]

    Consider $\A\bspec$. Since $\left\{ \bz_{j}\right\} _{j=1}^{\bk}$ are linearly independent,
    $\left\{ \bz_{j}-\bz_{1}\right\} _{j=2}^{\bk}$---which are the rows of $M\bspec$---are also linearly independent. For $\spec$ sufficiently close to $\bspec$, the rows of $M\spec$ will remain linearly independent. In this case, the linear system \eqref{eq:CAS_sys} is then necessarily solvable: $\A\spec$ is non-empty. Let $x_0$ be such a solution. Then, $\A\spec$ consists of all vectors $x \in \R^n$ such that $x{-}x_0$ is orthogonal to the $m{-}1$ linearly independent rows of $M\spec$. Thus, $\Dim\left\{\A\spec\right\}{=}n{-}\bk{+}1$. 

    The vectors $\left\{(z_i - z_j)\right\}_{j\neq i}$ clearly all lie in the rowspace of $M\spec$. Hence, the vectors$\left\{(z_i - z_j)\right\}_{j\neq i}$ are orthogonal to all direction in $\A\spec$.

    Finally, write $M$ instead of $M\spec$ for simplicity. Since $M$ has independent rows, the projection of $w$ onto $\A\spec$ is explicitly given by
    \begin{equation*}
    \projA{\spec}\left(w\right)=\left(I-M\left(M^{T}M\right)^{-1}M^{T}\right)w+M\left(M^{T}M\right)^{-1}b,
    \end{equation*}
    which varies smoothly with $\spec$ and $w$.
    \end{proof}

\begin{lem}
    \textbf{\label{lem:core} (Local Properties of Core)} For any ball-specifications $\spec$ sufficiently close to base ball-specifications $\bspec$, the core in \eqref{eq:core} is well-defined and varies smoothly with $\spec$.
    \end{lem}

\begin{lem}
    \textbf{(The Base Case)} \label{lem:linA}
    At base ball-specifications, the central affine subspace is a linear subspace and the core is non-zero.
    \end{lem}

\begin{proof}
    By Definition \ref{def:base}, $\br_{j}^{2}=\left\| \bz_{j}\right\| _{2}^{2}$
    for all $j$. Thus, \eqref{eq:CAS} simplifies to
    \begin{equation*}
    \A\bspec=\left\{ x\in\R^{n}:\ 2\bz_{j}^{T}x\text{ equal  for all } j=1,\dots,\bk\right\}.
    \end{equation*}
    Clearly, the origin satisfies the RHS conditions above, so $0\in\A\bspec$.

    \sloppy Next, assume for contradiction that $0{=}c\bspec$. By definition, $c\bspec$ is the projection of $\bz_j$ onto $\A\bspec$ for any $j$, so the vectors $\left\{ \bz_{j}-c\bspec\right\}_{j=1}^{\bk}{=}\left\{ \bz_{j}\right\} _{j=1}^{\bk}$ must be orthogonal to $\A\bspec$. The linear independence of $\left\{ \bz_{j}\right\}_{j=1}^{\bk}$ implies $\Dim\left\{ \A\bspec\right\}{\leq}n{-}\bk$, which contradicts the first fact of Lemma \ref{lem:A}. Thus, $0{\neq}c\bspec$.
    \end{proof}

\begin{lem}
    \textbf{(Local Properties of the Margin)\label{lem:margin}} 
    For ball-specifications $\spec$ near some base ball-specifications $\bspec$, the margin in \eqref{eq:margin} is well-defined, strictly-positive, and varies smoothly with $\spec$.
    \end{lem}

\begin{proof}
    It suffices to show that the square of the margin,\begin{equation}
    r_{j}^{2}-\left\| z_{j}-c\spec\right\| _{2}^{2}, \label{eq:margin_sq}
    \end{equation}
    does not depend on the index $j$, is strictly-positive, and varies smoothly with $\param$. First, consider the core and central affine subspace exactly at base ball-specifications $\bspec$. By Lemma
    \ref{lem:linA}, since $0 \in \A\bspec$ and $\projA{\bspec}\left(\bz_{j}\right){=}c\bspec{\neq}0$
    for all $j$, the definition of a projection gives
    \begin{equation*}
    \left\| \bz_{j}-c\bspec\right\| _{2}<\left\| \bz_{j}-0\right\| _{2}=\br_{j}\ \forall\ j=1,\dots,\bk.
    \end{equation*}
    Thus, \eqref{eq:margin_sq} is strictly positive, which implies the argument of the square-root in \eqref{eq:margin} is strictly positive. Next, observe that
    \begin{align*}
    r_{j}^{2}-\left\| z_{j}-c\spec\right\| _{2}^{2} & =-\left\| c\spec\right\| _{2}^{2}+\underbrace{2z_{j}^{T}c\spec-\left\| z_{j}\right\| _{2}^{2}+r_{j}^{2}}_{(\star)_j} \ \forall\  j=1,\dots,\bk.
    \end{align*}
    Since $c\spec{\in}\A\spec$, the term $(\star)_j$ is equal for all $j$. Therefore, \eqref{eq:margin_sq} is $j$-independent, and $\rho\spec$ in \eqref{eq:margin} is well-defined. The smoothness of $\rho\spec$  with respect to $\spec$ then follows directly from \eqref{eq:margin} and the smoothness of the core (Lemma \ref{lem:core}).
    \end{proof}

\begin{lem}
    \label{lem:B}\textbf{(Local Properties of the Feasible Region)} For ball-specifications
    $\spec$ near some base ball-specifications $\bspec$, the feasible region is nonempty and satisfies\begin{equation}
    \B\spec=\left\{ x\in\A\spec:\ \left\| x-c\spec\right\| _{2}=\rho\spec\right\}.\label{eq:Bdef2} 
    \end{equation}
    \end{lem}

\begin{proof}
    \noindent\textit{Equivalence of \eqref{eq:MBP_cons} and \eqref{eq:Bdef2}:}
    Expanding and rearranging \eqref{eq:MBP_cons} gives
    \begin{align*}
    \left\| x-z_{j}\right\| _{2}=r_{j}\ \forall\ j & \iff\left\| x\right\| _{2}^{2}=2z_{j}^{T}x-\left\| z_{j}\right\| _{2}^{2}+r_{j}^{2}\ \forall\ j\\
    & \implies2z_{j}^{T}x-\left\| z_{j}\right\| _{2}^{2}+r_{j}^{2}=2z_{i}^{T}x-\left\| z_{i}\right\| _{2}^{2}+r_{i}^{2}\ \forall\ i\neq j.
    \end{align*}
    Hence, $\B\spec\subseteq\A\spec$ implying
    \begin{equation*}
    \B\spec=\left\{ x\in\A\spec:\ \left\| x-z_{j}\right\| _{2}=r_{j}\text{  for all } j\right\}.
    \end{equation*}
    Since $c\left(r,Z\right){=}\projA{\spec}\left(z_{i}\right)$, for any $x{\in}\A\spec$, the vectors $\left(x{-}c\left(r,Z\right)\right)$ and $\left(z_{j}{-}c\spec\right)$ are orthogonal. Then, applying the Pythagorean Theorem to the equality condition in \eqref{eq:MBP_cons} gives
    \begin{equation*}
    r_{j}^{2} = \left\| x-z_i\right\|_{2}^{2} =\left\| x-c\left(r,Z\right)\right\| _{2}^{2}+\left\| z_{j}-c\spec\right\|_{2}^{2} \ \forall \ x\in\A\spec \text{ and } j=1,\dots,k.
    \end{equation*}
    We then deduce \eqref{eq:Bdef2} by subtracting $\left\| z_{j}{-}c\spec\right\|_{2}^{2}$ from the left and right sides, and applying the definition of $\rho\spec$ in \eqref{eq:margin}.

    \noindent \textit{Non-Emptiness of $\B\spec$:} By the first fact of Lemma \ref{lem:A}, the affine subspace $\A\spec$ is $(n{-}m{+}1)$-dimensional, so $\A\spec$ is a non-empty space. Thus, there exists $a\in\A\spec$ such that $a\neq c\spec$. Choose any such $a$ and consider the direction 
    \begin{equation*}
    d = \frac{1}{\left\| a-c\spec\right\|} \left(a-c\spec\right)
    \end{equation*}
    along with the vector
    \begin{equation*}
    v = c\spec+\rho\spec d.
    \end{equation*}
    Then, by construction,
    \begin{equation*}
    \left\| v-c\spec\right\| _{2}=\rho\spec.
    \end{equation*}
    Since $\A\spec$ contains both $c\spec$ and $d$, we deduce $v\in\A\spec$. Thus, $v$ satisfies all conditions in \eqref{eq:Bdef2}, so $v\in\B\spec$, and hence $\B\spec$ is non-empty.
    \end{proof}

\begin{thm}\label{thm:MBP_sol}
    \textbf{(Local, Explicit Solution of $\boldsymbol{MBP\param}$)} For parameters $\param$ near some base parameters $\bparam$, the optimal solution to $\MBP\param$ is unique, varies smoothly with $\param$, and is given by\begin{equation}\label{eq:x}
    x\param = c\spec+\rho\spec u\param,
    \end{equation}
    where\begin{equation}\label{eq:u}
    u\param = \frac{1}{\left\| \projA{\spec}\left(y\right)-c\spec\right\| _{2}}\left(\projA{\spec}\left(y\right)-c\spec\right).
    \end{equation}
    In particular, $x\bparam = 0$.
    \end{thm}

\begin{proof}
    \textit{The vector $u\param$ is well-defined:} To show the well-definedness of the expression in \eqref{eq:u}, observe the following at base parameters $\bparam$:

    \begin{align*}
    \projA{\bspec}\left(\by\right)-c\bspec &= \projA{\bspec}\left(-\sum_{j=1}^{\bk}\clam_{j}\bar{z}_{j}\right)-c\bspec &\text{ (By Definition \ref{def:base})}\\
    & = -\sum_{j=1}^{\bk}\clam_{j}\projA{\bspec}\left(\bar{z}_{j}\right)-c\bspec &\text{ (By linearity of $\A\bspec$ from Lemma \ref{lem:linA})}\\
    & = -\left(\sum_{j=1}^{\bk}\clam_{j}+1\right)c\bspec &\text{ (By definition of core \eqref{eq:core})}\\
    & \neq 0. &\text{ (By Definition \ref{def:base} and Lemma \ref{lem:linA})}.
    \end{align*}
    By the smoothness of the projection (third fact of Lemma \ref{lem:A}), we deduce $\projA{\spec}\left(y\right){-}c\spec{\neq}0$ for $\param$ sufficiently close to $\bparam$ as well. Thus, \eqref{eq:u} is well-defined. Moreover, the smoothness of the projection and \eqref{eq:u} further shows that $u\param$ is smooth with respect to $\param$.

    \noindent \textit{Derivation of $x\param$:} By Lemma \ref{lem:B}, $\B\spec\subseteq\A\spec$ so\begin{align*}
    x\param=\projB{\spec}\left(y\right) & =\projB{\spec}\left(\projA{\spec}\left(y\right)\right).
    \end{align*}
    Lemma \ref{lem:B} also states that $\B\spec$ is simply the $c\spec$-centered ball with radius $\rho\spec$ restricted to $\A\spec$. Thus, $\projB{\spec}\left(\projA{\spec}\left(y\right)\right)$ must be the (necessarily unique) point that
    \begin{enumerate}
        \item lies on the straight line from $c\spec$ to $\projA{\spec}\left(y\right)$, and
        \item is exactly the distance $\rho\spec$ from $c\spec$.
    \end{enumerate}
    Formalizing the above two criteria leads to the explicit-form
    \begin{equation*}
    x\param=c\spec+\frac{\rho\spec}{\left\| \projA{\spec}\left(y\right)-c\spec\right\| _{2}}\left(\projA{\spec}\left(y\right)-c\spec\right)=c\spec+\rho\spec u\param.
    \end{equation*}
    The smoothness of $x\param$ follows directly from the smoothness of the core (Lemma \ref{lem:core}), the margin (Lemma \ref{lem:margin}), and $u\param$ (shown above).

    \noindent \textit{Demonstration of $x\bparam{=}0$:} Observe that the Lagrangian of $\MBP\bparam$ is
    \[
    \L(x,\lambda) = \left\| x-\by\right\| _{2}^{2} + \sum_{j=1}^\bk \lambda_j \left\| x-\bz_{j}\right\| _{2}^{2},
    \]
    where $\lambda_j$ is the $j$-th element of a Lagrange multipliers vector $\lambda \in \R^\bk$. By Definitions \ref{def:MBP}-\ref{def:base}, the zero-vector is a feasible solution to $\MBP\bparam$. A feasible vector $x^*$ is the solution of $\MBP\bparam$ if and only if there exists $\lambda^*$ such that $x^*$ minimizes $\L(\cdot,\lambda^*)$. It is easy to check using Definition \ref{def:base} and first-order optimality conditions that $x^*{=}0$ is the unique minimizer of $\L(\cdot,\clam)$. Thus, $x\bparam{=}0$ is the unique solution to $\MBP\bparam$.
    \end{proof}

\begin{lem}\label{lem:MBP_lam}\textbf{(Properties of MBP Lagrange Multipliers)} Suppose the parameters $\param$ are sufficiently close to base parameters $\bparam$ with corresponding base weights vector $\clam$. Consider the optimal solution $x\param$ of $\MBP\param$. Then, the following hold:
    \begin{enumerate}
        \item There exists a unique Lagrange multiplier vector, $\lambda\param\in\R_{++}^{\bk}$, satisfying the stationarity condition \eqref{eq:MBP_FOC}.
        \item The vector $\lambda\param$ varies smoothly with $\param$.
        \item At the base parameters, $\lambda\bparam=\clam$.
    \end{enumerate}
    \end{lem}

\begin{proof}
    Since $x\param$ is optimal for $\MBP\param$, there must exist a Lagrange multipliers vector $\lambda\param\in\R^{\bk}$ satisfying \eqref{eq:MBP_FOC}. We first show $\lambda\param$ is unique. Finding Lagrange multipliers satisfying \eqref{eq:MBP_FOC} is equivalent to finding minimizers of the function
    \begin{equation*}
    F\left(\lambda\right)=\left\| x\param-y+X\lambda\right\| _{2}^{2},
    \end{equation*}
    where we define the matrix
    \[X=\begin{bmatrix}x\param{-}z_{1}, \dots, x\param{-}z_{\bk}\end{bmatrix}\in\R^{n\times\bk}.\]
    Then, a vector $\lambda$ minimizes $F$ if and only if it satisfies the below $\bk\times\bk$ linear system:
    \begin{equation*}
    X^{T}\left(x\param-y+X\lambda\right)=0\iff X^{T}X\lambda=X^{T}\left(y-x\param\right).
    \end{equation*}
    By Theorem \ref{thm:MBP_sol}, for $\param$ close to $\bparam$, the MBP-solution $x\param$ is close to zero. Therefore, columns of $X$ are close to $\left\{-\bz_{j}\right\}_{j=1}^{\bk}$, which are linearly independent (Definition \ref{def:base}). This implies $X^{T}X$ is invertible, and the minimizer of $F$ is unique and explicitly given by 
    \begin{equation*}
    \lambda\param = \argmin_\lambda F\left(\lambda\right)=\left(X^{T}X\right)^{-1}X^{T}\left(y-x\param\right).
    \end{equation*}
    The smoothness of $\lambda\param$ with respect to $\param$ follows from the smoothness of $x\param$ (Theorem \ref{thm:MBP_sol}) and the smoothness of the above matrix operations. 

    Finally, it follows directly from Definition \ref{def:base} and Theorem \ref{thm:MBP_sol} that
    \begin{equation*}
    x\bparam-\by+\sum_{j=1}^{\bk}\clam_{j}\left[x\bparam-\bz_{j}\right]=0,
    \end{equation*}
    which implies the Lagrange multiplier vector at the base parameters is uniquely $\lambda\bparam=\clam$.
    \end{proof}

\begin{thm}\textbf{(Inequality-Constrained MBP)}\label{thm:MBP_ineq}
    Consider the following inequality-constrained MBP:
    \begin{align*}
    %\begin{aligned}
    \min_{x\in\R^{n}}\ & \left\| x-y\right\| _{2}^{2}\\
    \mathrm{s.t.}\ & \left\| x-z_{j}\right\| _{2}^{2} \leq r_{j}^{2}\ \forall\ j=1,\dots,\bk,
    %\end{aligned}%\label{eq:MBP_ineqFull}
    \end{align*}
    and denote it as $\MBPl\param$. For parameters $\param$ sufficiently close to $\bparam$, $\MBPl\param$ is feasible and possesses the same unique optimal solution, $x\param$, and unique Lagrange multipliers, $\lambda\param$, as $\MBP\param$. Consequently, all constraints of $\MBPl\param$ are tight. Moreover, the optimal solution and multipliers satisfy\begin{equation}
    x\param = \mathrm{O}\left(\|\param-\bparam\|\right)\text{ and } \lambda\param = \clam + \mathrm{O}\left(\|\param-\bparam\|\right).\label{eq:MBP_Onotation}
    \end{equation}
    \end{thm}

\begin{proof}
    The feasibility of $\MBPl\param$ follows directly from Lemma \ref{lem:B} since $\B\param$ is a subset of the feasible region of $\MBPl\param$.

    $\MBPl\param$ possesses a unique minimizer since it minimizes a strongly convex objective on a convex feasible region. Moreover, checking the KKT conditions is sufficient for demonstrating optimality because the $\|x - z_j\|_2^2$-term in the constraints is convex and differentiable for all $j$. Therefore---denoting the unique pair of optimal solutions and Lagrange multipliers of $\MBP\param$ as $\left(x\param, \lambda\param\right)$---it suffices to check that $\left(x\param, \lambda\param\right)$ satisfies the KKT conditions of $\MBPl\param$:
    \begin{enumerate}
        \item \textbf{(Stationarity)} Follows from $\MBPl\param$ and $\MBP\param$ having the same stationarity condition \eqref{eq:MBP_FOC}.
        \item \textbf{(Primal Feasibility)} Follows from $\B\param$ being a subset of the feasible region of $\MBPl\param$.
        \item \textbf{(Dual Feasibility)} The inequality constraints of $\MBPl\param$ require the non-negativity of all Lagrange multipliers. By Definition \ref{def:base}, the elements of $\clam$ are strictly-positive. Thus, by Lemma \ref{lem:MBP_lam}, the elements of $\lambda\param$ are also strictly-positive for $\param$ sufficiently close to $\bparam$.
        \item \textbf{(Complementary Slackness)} \sloppy By construction, $x\param$ satisfies all the inequality constraints of $\MBPl\param$ with equality. Correspondingly, $\lambda\param$ are all strictly positive.
    \end{enumerate}
    Therefore, $\left(x\param, \lambda\param\right)$ is the unique pair of optimal solutions and Lagrange multipliers for $\MBPl\param$ as well. The characterizations in \eqref{eq:MBP_Onotation} directly follows from Theorem \ref{thm:MBP_sol} and Lemma \ref{lem:MBP_lam} as well as recalling that smooth functions are locally Lipschitz.
    \end{proof}

