\mu_{k} =\blam_{k}-\left(1-\sum_{j=1}^{k-1}\lambda_{j}\right) =\blam_{k}-\left(1-\sum_{j=1}^{k-1}\blam_{j}\right)+\mathrm{O}\left(\left\| \S\right\| \right) =\mathrm{O}\left(\left\| \S\right\| \right).
\end{equation*}
Thus,\begin{equation}
    \mu_j = \mathrm{O}(\|\S\|) \ \forall \ j=1,\dots,k.\label{eq:mu_size}
\end{equation}

Substituting \eqref{eq:mu} into \eqref{eq:FOC2}, applying identities \eqref{eq:lam_sum1}-\eqref{eq:lam_sum0}, collecting $\mathrm{O}\left(\|\S\|^2\right)$ terms, and solving for $s_k^{+}$ gives\begin{equation}s_{k}^{+}= \frac{1}{2-\blam_{k}}\left[s_{k}-\frac{\blam_{k}}{L}\nabla f_{k}\left(s_{k}\right)\right]+\sum_{j=1}^{k-1}\frac{\blam_{j}}{2-\blam_{k}}\left[s_j - \frac{1}{L} \nabla f_j(s_j)\right]+\frac{1}{L\left(2-\blam_{k}\right)}\sum_{j=1}^{k}\mu_{j}\nabla f_j(s_j) +\mathrm{O}\left(\left\| \S\right\| ^{2}\right).\label{eq:pre_sform}
\end{equation}
Adopting the notation \eqref{eq:A_notation} and applying the Taylor expansion \eqref{eq:taylor}, observe\begin{equation}
    \sum_{j=1}^{k}\mu_{j}\nabla f_j(s_j) = \sum_{j=1}^{k}\mu_{j}\left(a_j + A_j s_j + \nabla r_j (s_j)\right) = \sum_{j=1}^{k}\mu_{j}a_j +\mathrm{O}\left(\left\| \S\right\|^{2}\right),\label{eq:sum_muA}
\end{equation}
where last equality follows from \eqref{eq:mu_size} and Lemma \ref{lem:r_grad}. Substituting \eqref{eq:sum_muA} into \eqref{eq:pre_sform} then leads to\begin{equation}
s_{k}^{+}=\frac{1}{2-\blam_{k}}\left[s_{k}-\frac{\blam_{k}}{L}\nabla f_{k}\left(s_{k}\right)\right]+\sum_{j=1}^{k-1}\frac{\blam_{j}}{2-\blam_{k}}\left[s_j - \frac{1}{L} \nabla f_j(s_j)\right]+\frac{1}{L\left(2-\blam_{k}\right)}\underbrace{\sum_{j=1}^{k}\mu_{j}a_j}_{(\star)} +\mathrm{O}\left(\left\| \S\right\| ^{2}\right).
\label{eq:s_form}
\end{equation}

Next, again combine \eqref{eq:lambda}-\eqref{eq:mu} with equation \eqref{eq:lam_sum1} to deduce
\begin{equation*}
\sum_{j=1}^{k}\mu_{j}=\sum_{j=1}^{k}\left(\blam_{j}-\lambda_{j}\right)=0.
\end{equation*}
Then, it follows from \eqref{eq:Udef2} that $\proj\left[(\star)\right]=0$.
The desired result then follows from applying $\proj$ to \eqref{eq:s_form}.

\begin{lem}\label{lem:Up_component}
Assume Setting \ref{setting:localSD}, and let $\bx{=}0$. Then, $s_{i}^{+}$ satisfies
\begin{equation*}
\projp\left[s_{i}^{+}\right]=\mathrm{O}\left(\left\| \S\right\| ^{2}\right) \ \forall \ i=1,\dots,k.
\end{equation*}
where $\projp$ is the projection operator onto the orthogonal complement of the $\U$-subspace \eqref{eq:Udef1}.
\end{lem}

\begin{proof}
Consider any fixed $i$. By Theorem \ref{thm:SD_MBP}, the constraints of $\left(P_{i}^{\S}\right)$
are tight. Thus, by Observation \ref{obs:SD_MOS}, $s_{i}^{+}$ satisfies
\begin{equation*}
    f_{j}\left(s_{j}\right)+\nabla f_{j}\left(s_{j}\right)^{T}\left(s_i^+-s_{j}\right)+\frac{L}{2}\left\| s_i^+-s_{j}\right\| _{2}^{2} = f_{i}\left(s_{i}\right)+\nabla f_{i}\left(s_{i}\right)^{T}\left(s_i^+-s_{i}\right) \ \forall \ j\neq i.
\end{equation*}
Using equation \eqref{eq:taylor} in the above gives, for all $j\neq i$,
\begin{multline*}
    f(0) + a_{j}^{T}s_{j}+\frac{1}{2}s_{j}^{T}A_{j}s_{j}+r_{j}\left(s_j\right)+\left(a_{j}+A_{j}s_{j} + \nabla r_j(s_j)\right)^T\left(s_{i}^{+}-s_{j}\right)+\frac{L}{2}\left\Vert s_{i}^{+}-s_{j}\right\Vert _{2}^{2}\\
    =f(0) + a_{i}^{T}s_{i}+\frac{1}{2}s_{i}^{T}A_{i}s_{i}+r_{i}\left(s_i\right)+\left(a_{i}+A_{i}s_{i}+\nabla r_i(s_i)\right)^T\left(s_{i}^{+}-s_{i}\right).
\end{multline*}
After simplification and rearrangement, we obtain\begin{equation}
\left(a_{j}-a_{i}\right)^{T}s_{i}^{+}=-\left(A_{j}s_{j}-A_{i}s_{i}+\nabla r_{j}\left(s_{j}\right)-\nabla r_{i}\left(s_{i}\right)\right)^{T}s_{i}^{+}-\frac{L}{2}\left\| s_{i}^{+}-s_{j}\right\| _{2}^{2}-c_{j}\left(s_{j}\right)+c_{i}\left(s_{i}\right)  \ \forall \ j\neq i, \label{eq:s_constr}
\end{equation}
where we define the functions
\begin{equation*}
c_{j}\left(x\right)\equiv-\frac{1}{2}x^{T}A_{j}x+r_{j}\left(x\right)-\nabla r_{j}\left(x\right)^{T}x \ \forall \ j=1,\dots,i.
\end{equation*}
By Lemma \ref{lem:r_grad}, $c_j(x)$ is $O\left(\|x\|^2\right)$. Since we assume $\bx{=}0$, by Theorem \ref{thm:SD_MBP}, $s_{i}^{+}=\mathrm{O}\left(\left\| \S\right\| \right)$.
We then deduce that all terms on the right-hand side of \eqref{eq:s_constr} are $\mathrm{O}\left(\left\| \S\right\|^2 \right)$:
\begin{equation}
\left(a_{j}-a_{i}\right)^{T}s_{i}^{+}=\mathrm{O}\left(\left\| \S\right\|^2 \right) \ \forall \ j\neq i.\label{eq:projsp}
\end{equation}
