\begin{lem}
    \textbf{(The Base Case)} \label{lem:linA}
    At base ball-specifications, the central affine subspace is a linear subspace and the core is non-zero.
    \end{lem}

\begin{proof}
    By Definition \ref{def:base}, $\br_{j}^{2}=\left\| \bz_{j}\right\| _{2}^{2}$
    for all $j$. Thus, \eqref{eq:CAS} simplifies to
    \begin{equation*}
    \A\bspec=\left\{ x\in\R^{n}:\ 2\bz_{j}^{T}x\text{ equal  for all } j=1,\dots,\bk\right\}.
    \end{equation*}
    Clearly, the origin satisfies the RHS conditions above, so $0\in\A\bspec$.

    \sloppy Next, assume for contradiction that $0{=}c\bspec$. By definition, $c\bspec$ is the projection of $\bz_j$ onto $\A\bspec$ for any $j$, so the vectors $\left\{ \bz_{j}-c\bspec\right\}_{j=1}^{\bk}{=}\left\{ \bz_{j}\right\} _{j=1}^{\bk}$ must be orthogonal to $\A\bspec$. The linear independence of $\left\{ \bz_{j}\right\}_{j=1}^{\bk}$ implies $\Dim\left\{ \A\bspec\right\}{\leq}n{-}\bk$, which contradicts the first fact of Lemma \ref{lem:A}. Thus, $0{\neq}c\bspec$.
    \end{proof}

